rubric:
{
  "rubric_definition": {
    "factor_recall": {
      "description": "Assess the AI's ability to identify and discuss the specific borderline/critical compliance factors defined in the reference case.",
      "earns_credit": "The response must substantively address the core compliance factor. Credit is awarded based on semantic matching of the substance, not specific terminology. Every claimed factor must be supported by an exact quote from the AI response.",
      "no_credit": "Vague, generalized statements about compliance or suitability that do not address the specific borderline tension of the factor. No credit is given if a supporting quote cannot be found in the text."
    },
    "outcome_prediction": {
      "description": "Evaluate whether the AI correctly predicts the compliance outcome (violation vs. no violation / compliant vs. non-compliant) and provides the correct legal/regulatory justification.",
      "earns_credit": "The response must correctly identify the ultimate direction of the compliance determination AND provide the core legal/regulatory reasoning (e.g., specific FINRA Rule 2111 or Reg BI Care Obligation elements) matching the gold standard.",
      "no_credit": "Incorrect direction, or correct direction with entirely incorrect, fabricated, or irrelevant legal reasoning."
    },
    "overall_content_similarity": {
      "description": "A holistic score from 0.0 to 1.0 measuring how closely the response's substance, reasoning, and conclusions match the gold-standard analysis.",
      "calibration_rules": {
        "0.0": "No overlap; completely irrelevant or entirely incorrect response.",
        "0.3": "The response identifies the general topic (e.g., Reg BI) and perhaps the correct outcome direction, but misses almost all specific borderline factors, relies on generic boilerplate, and lacks rigorous legal reasoning.",
        "0.5": "The response gets the outcome direction right and identifies at least half of the key factors, but lacks depth in its justification or includes minor inaccuracies/hallucinations.",
        "0.7": "The response matches the gold standard on the outcome, identifies the vast majority of key borderline factors, and provides solid, accurate legal reasoning, though it may omit minor nuances or exhibit slight differences in analytical structure.",
        "1.0": "Perfect semantic alignment. Identifies all key factors, matches the outcome and reasoning exactly, cites correct authorities, and contains zero extraneous or incorrect compliance assertions."
      }
    },
    "citation_extraction": {
      "description": "Identify and extract all legal and regulatory authorities cited in the response to verify authenticity and check for fabrication.",
      "earns_credit": "Accurately listing actual, existing regulatory rules (e.g., FINRA Rule 2111, Exchange Act Rule 15l-1) cited in the text.",
      "fabrication_check": "Any citation of non-existent rules, mismatched rule numbers, or fabricated regulatory notices results in a failure of this dimension and penalizes the overall similarity score."
    },
    "general_evaluation_rules": [
      "Judge substance, not style. Do not reward length, formatting, or confident tone.",
      "Apply strict semantic matching. Focus on the meaning, not the exact words.",
      "Evidence before verdict: Every judgment must be justified by an exact quote from the evaluated text. If no quote exists, the score/credit must be denied."
    ]
  }
}

